<?php $title='تنظیمات پایه و کاربران'; ?>
<div class="grid"><div class="col-4 card"><h2>دسته/واحد/انبار</h2><form method="post" action="<?= e(base_url('settings/save-basic')) ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><label>نوع</label><select name="kind"><option value="category">دسته‌بندی</option><option value="unit">واحد کالا</option><option value="warehouse">انبار</option></select><label>نام</label><input name="name" required><label>توضیح/نماد/مکان</label><input name="extra"><button class="btn">ذخیره</button></form></div><div class="col-4 card"><h2>کاربر جدید</h2><form method="post" action="<?= e(base_url('users/save')) ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><label>نام</label><input name="name" required><label>نام کاربری</label><input name="username" required><label>رمز</label><input type="password" name="password" required><label>نقش</label><select name="role"><option value="keeper">انباردار</option><option value="manager">مدیر انبار</option><option value="viewer">مشاهده‌گر</option><option value="admin">ادمین</option></select><button class="btn">ساخت کاربر</button></form></div><div class="col-4 card"><h2>کاربران</h2><?php foreach($users as $u): ?><p><?= e($u['name']) ?> - <?= e($u['username']) ?> <span class="badge"><?= e($u['role']) ?></span></p><?php endforeach; ?></div></div>
<div class="grid"><div class="col-4 card"><h2>دسته‌ها</h2><?php foreach($categories as $c): ?><p><?= e($c['name']) ?></p><?php endforeach; ?></div><div class="col-4 card"><h2>واحدها</h2><?php foreach($units as $u): ?><p><?= e($u['name']) ?> <?= e($u['symbol']) ?></p><?php endforeach; ?></div><div class="col-4 card"><h2>انبارها</h2><?php foreach($warehouses as $w): ?><p><?= e($w['name']) ?></p><?php endforeach; ?></div></div>
